/* ── Status Dot ─────────────────────────────────────────── */

.component-{{id}} {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: {{dotSize}}px;
  height: {{dotSize}}px;
  flex-shrink: 0;
}

/* Solid core dot */
.component-{{id}} .status-dot__core {
  position: relative;
  z-index: 1;
  width: {{dotSize}}px;
  height: {{dotSize}}px;
  border-radius: 9999px;
}

/* Expanding/fading ring */
.component-{{id}} .status-dot__ring {
  position: absolute;
  inset: 0;
  border-radius: 9999px;
  opacity: 0.6;
  animation: status-dot-pulse-{{id}} 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

/* Available: emerald */
.component-{{id}}.status-dot--available .status-dot__core,
.component-{{id}}.status-dot--available .status-dot__ring {
  background-color: #00b981;
}

/* Unavailable: red */
.component-{{id}}.status-dot--unavailable .status-dot__core,
.component-{{id}}.status-dot--unavailable .status-dot__ring {
  background-color: #fb2c36;
}

/* Pulse keyframes — scoped per instance */
@keyframes status-dot-pulse-{{id}} {
  0%, 100% {
    transform: scale(1);
    opacity: 0.6;
  }
  50% {
    transform: scale(2.2);
    opacity: 0;
  }
}

